    ov.innerHTML = '<button class="vp-close" aria-label="Close player">×</button><div class="vp-stage"></div>';
    ov.addEventListener('click', e => { if (e.target === ov) closePlayer(); });
    ov.querySelector('.vp-close').addEventListener('click', closePlayer);
