      // so by the click Close is back under the finger. That press only brings the controls back.
      window.addEventListener('pointerdown', () => { downWhileOff = ov.classList.contains('open') && ov.classList.contains('vp-chrome-off') ? Date.now() : 0; }, true);
      ov.addEventListener('pause', wakeChrome, true);
